type Menu = "kopi" | "teh" | "roti";
const harga: Record<Menu, number> = { kopi: 18000, teh: 12000, roti: 15000 };
const terjual: Record<string, number> = {};
const transaksi: Menu[] = ["kopi", "teh", "kopi", "roti", "kopi"];
for (const menu of transaksi) {
  terjual[menu] = (terjual[menu] ?? 0) + 1;
}
console.log(terjual);
let pendapatan = 0;
for (const menu of transaksi) {
  pendapatan += harga[menu];
}
console.log("Pendapatan:", pendapatan);

