type Status = "menunggu" | "dibayar" | "dikirim";
const label: Record<Status, string> = {
  menunggu: "Menunggu pembayaran",
  dibayar: "Sudah dibayar",
  dikirim: "Dalam pengiriman",
};
const daftar: Status[] = ["dibayar", "menunggu"];
for (const s of daftar) {
  console.log(label[s]);
}
